@contextmanager
def maintenance(lb, host):
    lb.drain(host)
    try: yield
    finally: lb.enable(host)

with maintenance(lb, "web1"): upgrade("web1")

def retry(n):
    def deco(fn):
        @wraps(fn)
        def w(*a, **k):
            for i in range(n):
                try: return fn(*a, **k)
                except IOError: time.sleep(2**i)
            return fn(*a, **k)
        return w
    return deco

@retry(3)
def fetch(): ...

class Check:
    registry = {}
    def __init_subclass__(cls, **kw):
        super().__init_subclass__(**kw)
        Check.registry[cls.__name__] = cls

class DiskCheck(Check): ...
